const express = require("express");
const cors = require("cors");
const commentsRouter = require("./routes/comments");
const { errorHandler } = require("./middleware/errorHandler");

const app = express();

app.use(cors());
app.use("/api", commentsRouter);
app.use(errorHandler);

module.exports = { app };

